#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""ТІЛЬКИ ЧИТАННЯ. Табличні частини платіжних документів — чим вони чіпляються до угоди."""
import collections, os, sys, urllib.parse
BASE = "/root/unitex-finrep"
sys.path.insert(0, os.path.join(BASE, "engine"))
os.chdir(BASE)
from odata_client import ODataClient
c = ODataClient()

def get(p):
    return c._get(urllib.parse.quote(p, safe="/?&=$,'"))

def page(ent, sel=None):
    out, skip = [], 0
    while True:
        p = "/%s?$format=json&$top=1000&$skip=%d" % (ent, skip)
        if sel:
            p += "&$select=" + ",".join(sel)
        b = get(p)["value"]
        out += b
        if len(b) < 1000:
            return out
        skip += 1000

def blank(x):
    return (not x) or str(x).startswith("00000000-0000")

for ent in ("Document_СписаниеДенСредств_Счета", "Document_Приход_Счета"):
    rows = page(ent)
    print("\n### %s — %d рядків" % (ent, len(rows)))
    keys = [k for k in rows[0] if not k.endswith("@navigationLinkUrl")]
    print("   поля:", ", ".join(keys))
    for k in keys:
        if k.endswith("_Key"):
            filled = sum(1 for r in rows if not blank(r.get(k)))
            print("     %-28s заповнено %d з %d" % (k, filled, len(rows)))

# чи ведуть посилання на витратні накладні / доходні рахунки
rn = {r["Ref_Key"]: r for r in page("Document_РасходнаяНакладная",
      ["Ref_Key", "Number", "Сделка_Key", "Услуга_Key", "Сумма_УЕ", "ВидОплаты_Key", "Через_Key"])}
sch = {r["Ref_Key"]: r for r in page("Document_Счет", ["Ref_Key", "Number", "Сделка_Key"])}
print("\n=== куди ведуть посилання у Document_СписаниеДенСредств_Счета ===")
rows = page("Document_СписаниеДенСредств_Счета")
cnt = collections.Counter()
for r in rows:
    for k, v in r.items():
        if k.endswith("_Key") and not blank(v):
            if v in rn:
                cnt["%s → витратна накладна" % k] += 1
            elif v in sch:
                cnt["%s → доходний рахунок" % k] += 1
for k, n in cnt.most_common():
    print("   %-50s %d" % (k, n))

print("\n=== скільки витратних накладних мають заповнене «Через» ===")
allrn = list(rn.values())
print("   усього витратних:", len(allrn))
print("   з заповненим Через_Key:", sum(1 for r in allrn if not blank(r.get("Через_Key"))))
print("   з заповненим Сделка_Key:", sum(1 for r in allrn if not blank(r.get("Сделка_Key"))))
PYEOF
